result:
Assumed stack: Node + Express + Redis (`ioredis`). Cache-aside pattern: read from cache, fall back to the DB on a miss, and invalidate on write.

```js
// profileCache.js
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);

const TTL = 300; // seconds
const key = (id) => `profile:${id}`;

async function getProfile(id, loadFromDb) {
  try {
    const hit = await redis.get(key(id));
    if (hit) return JSON.parse(hit);
  } catch (e) {
    console.warn('cache read failed', e.message); // degrade to DB, don't fail request
  }

  const profile = await loadFromDb(id);
  if (profile) {
    redis.set(key(id), JSON.stringify(profile), 'EX', TTL).catch(() => {});
  }
  return profile;
}

async function invalidateProfile(id) {
  await redis.del(key(id));
}

module.exports = { getProfile, invalidateProfile };
```

```js
// routes.js
const { getProfile, invalidateProfile } = require('./profileCache');

app.get('/users/:id/profile', auth, async (req, res) => {
  if (req.user.id !== req.params.id && !req.user.isAdmin) return res.sendStatus(403);
  const profile = await getProfile(req.params.id, db.users.findProfileById);
  if (!profile) return res.sendStatus(404);
  res.set('Cache-Control', 'private, no-store');
  res.json(profile);
});

app.put('/users/:id/profile', auth, async (req, res) => {
  if (req.user.id !== req.params.id) return res.sendStatus(403);
  const updated = await db.users.updateProfile(req.params.id, req.body);
  await invalidateProfile(req.params.id); // invalidate after the DB write commits
  res.json(updated);
});
```

Gotchas:
- The authorization check runs before the cache lookup. If the cache were checked first, any user could read another user's cached profile.
- Use `Cache-Control: private` so CDNs and proxies never store personal data.
- A Redis outage only causes cache misses. Requests still succeed from the DB.

Skipped: stampede protection (lock or single-flight). Add it if profile reads spike hard on hot keys.
